// Telegram-Update vereinheitlichen (Nachricht, Sprachnachricht, Knopfdruck).
const roh = $input.first().json ?? {};
const b = (roh.body && typeof roh.body === 'object') ? roh.body : null;
const quelle = (b && (b.message || b.callback_query || b.edited_message)) ? b : roh;
const istTest = !!(roh.body || roh.webhookUrl);
const schluessel = String((roh.query && roh.query.schluessel) || quelle.schluessel || '');
const cq = quelle.callback_query || null;
const m = quelle.message || (cq && cq.message) || {};
const von = (cq && cq.from) || m.from || {};
const stimme = m.voice || m.audio || null;
return [{ json: {
  chatId: String((m.chat && m.chat.id) !== undefined ? m.chat.id : ''),
  text: (m.text || '').trim(),
  istSprache: !!stimme,
  stimmeDateiId: stimme ? String(stimme.file_id || '') : '',
  stimmeTestUrl: (stimme && stimme.test_url) ? String(stimme.test_url) : '',
  messageId: (cq && cq.message ? cq.message.message_id : m.message_id) || null,
  userName: [von.first_name, von.last_name].filter(Boolean).join(' ') || von.username || '',
  isCallback: !!cq,
  istTest, schluessel,
  eingang: new Date().toISOString(),
} }];

// Sprachnachricht: nur den Text weitergeben, deuten laesst der Agent deuten.
const felder = $('Eingabe').item.json;
const roh = $input.first().json || {};
if (roh.error) {
  return [{ json: Object.assign({}, felder, { text: '',
    antwort: '\u26a0\ufe0f Die Sprachnachricht konnte nicht verarbeitet werden.' }) }];
}
const sauber = String(roh.text || '').replace(/\s+/g, ' ').trim();
if (!sauber) {
  return [{ json: Object.assign({}, felder, { text: '',
    antwort: '\U0001f3a7 Ich habe nichts verstanden - bitte nochmal sprechen.' }) }];
}
return [{ json: Object.assign({}, felder, { text: sauber, gehoert: sauber }) }];

const j = $json;
return [{ json: { chatId: j.chatId || $('Eingabe').item.json.chatId,
  antwort: '\U0001f3a7 Verstanden: \u00bb' + (j.gehoert || '') + '\u00ab' } }];

// Nur der Betreiber darf den Sender steuern.
const d = $getWorkflowStaticData('global');
if (!Array.isArray(d.erlaubte)) d.erlaubte = (d.erlaubte ? [d.erlaubte] : []);
const j = $json;
if (j.istTest && (!d.testSchluessel || j.schluessel !== d.testSchluessel)) {
  return [{ json: Object.assign({}, j, { erlaubt: false, neuerBetreiber: false }) }];
}
let erlaubt = false;
let neu = false;
if (d.erlaubte.length === 0 && j.chatId) {
  d.erlaubte.push(j.chatId);
  erlaubt = true;
  neu = true;
} else {
  erlaubt = d.erlaubte.includes(j.chatId);
}
return [{ json: Object.assign({}, j, { erlaubt, neuerBetreiber: neu }) }];

const j = $json;
return [{ json: Object.assign({}, j, { antwort: j.neuerBetreiber
  ? '\u2705 Diesen Chat als Betreiber eingetragen. Schreib einfach, was laufen soll.'
  : '\u26d4 Kein Zugang. Dieser Bot ist auf den Betreiber beschraenkt.' }) }];

// Nachricht ohne Text (Knopfdruck, Bild, Sticker) - nichts zu steuern.
const j = $('Eingabe').first().json;
return [{ json: { chatId: j.chatId,
  antwort: 'Das habe ich nicht verstanden. Schreib zum Beispiel: spiele Juliet von Modern Talking.',
  tastatur: null } }];

// Ist die Antwort des Agenten brauchbar? Wenn nicht, muss der Ablauf den Befehl
// selbst ausfuehren (Ersatzweg) - ein Wunsch darf nicht daran scheitern, dass
// das Sprachmodell nichts, Unsinn oder nur einen Fehler liefert.
const eingang = $('Eingabe').first().json;
const text = String(eingang.text || '').trim();
// Ohne Text gibt es nichts auszufuehren (Knopfdruck, Bild, Sticker).
if (!text) {
  return [{ json: { chatId: eingang.chatId, ersatz: false, grund: 'kein Text',
    antwort: 'Das habe ich nicht verstanden. Schreib zum Beispiel: spiele Juliet von Modern Talking.' } }];
}
const roh = String(($json && ($json.output || $json.text)) || '').trim();
const fehler = /there was an error|es gab einen fehler|fehler beim|nicht ausgef(ue|ü)hrt|konnte nicht|unable to|i cannot|i can't/i.test(roh);
const ersatz = roh.length < 3 || fehler;
return [{ json: {
  chatId: eingang.chatId,
  antwort: roh,
  ersatz: ersatz,
  grund: roh.length < 3 ? 'leere Antwort' : (fehler ? 'Fehlermeldung' : ''),
} }];

// Ersatzweg ohne Sprachmodell: den Befehl aus der Nachricht selbst lesen.
// (Dieselbe Idee wie im frueheren Wunschbot: freier Text = Wunsch.)
const j = $('Eingabe').first().json;
const original = String(j.text || '');
let t = original
  .replace(/\b(spiele|spiel|mach|leg|gib|starte|setz|dreh|schmeiss|hau|bitte|mal|doch|sofort|jetzt|einmal|nochmal|wieder)\b/gi, ' ')
  .replace(/\b(wechsel|wechseln|change|die|der|das|den|dem|musik|musikrichtung|richtung|auf|an|mir|uns|was|etwas|irgendwas|irgendein|irgendeine|nummer)\b/gi, ' ')
  .replace(/\b(von|aus|fuer|für|mit|im|in)\b/gi, ' ')
  .replace(/[^\wäöüÄÖÜß0-9.\- ]+/g, ' ')
  .replace(/\s+/g, ' ').trim();

// Stimmungsworte, die der Katalogdienst kennt (gleiche Liste wie im Werkzeug).
const stimmungen = [
  [/peppig|flott|fetzig|party|tempo|abgehen|abgeht|tanz|tanzen/i, 'party'],
  [/ruhig|entspannt|smooth|leise|sanft|chill|relax/i, 'ruhig'],
  [/hart|laut|metal|heavy/i, 'metal'],
  [/rap|hip.?hop/i, 'hiphop'],
  [/klassik|klassisch|orchester/i, 'klassik'],
  [/schlager/i, 'schlager'],
  [/disco|funk/i, 'disco'],
  [/punk/i, 'punk'],
  [/jazz|swing/i, 'jazz'],
  [/blues/i, 'blues'],
  [/folk|country/i, 'folk'],
  [/techno|electronic|elektro|house|dance/i, 'electronic'],
  [/80er|achtziger/i, '80er'],
  [/90er|neunziger/i, '90er'],
];
const genres = ['rock', 'pop', 'dance', 'party', 'metal', 'jazz', 'blues', 'schlager',
                'punk', 'hiphop', 'disco', 'klassik', 'folk', 'electronic', 'grunge',
                'deutschrap', 'rap', 'gothic', 'wave'];

let stimmung = '';
for (const [muster, wort] of stimmungen) {
  if (muster.test(original)) { stimmung = wort; break; }
}
// Wie viele Worte bleiben uebrig, wenn man Stimmung und Genre abzieht?
const reste = t.split(' ').filter((w) => w && !genres.includes(w.toLowerCase()));
const genreImText = t.split(' ').map((w) => w.toLowerCase()).find((w) => genres.includes(w));

let richtung = '';
if (stimmung && reste.length <= 1) richtung = stimmung;
else if (genreImText && reste.length <= 1) richtung = genreImText;

return [{ json: {
  chatId: j.chatId,
  text: j.text,
  suchtext: t || original.trim(),
  richtung: richtung,
  einreihen: /danach|spaeter|später|anschliessend|hinterher/i.test(original),
  // Verwaltungsauftraege (Wiedergabelisten, Anlage, Nutzer, Sicherung, ...) haben
  // keinen Ersatzweg - eine Titelsuche waere hier Unsinn. Solche Nachrichten
  // duerfen NICHT als Musikwunsch enden.
  verwaltung: /wiedergabeliste|playlist|anlage|station|sender|benutzer|nutzer|rolle|sicherung|backup|einstellung|option|bericht|report|statistik|zuhoerer|zuhörer|hochladen|upload|loeschen|löschen|anlegen|aendern|ändern|neustart|neu starten|aktualisieren/i.test(original),
} }];

// Der Auftrag sah nach Verwaltung aus (Wiedergabeliste, Anlage, Nutzer ...).
// Dafuer gibt es keinen Ersatzweg ohne Sprachmodell - eine Titelsuche waere
// falsch. Deshalb ehrlich melden und um Wiederholung bitten.
return [{ json: {
  chatId: $('Eingabe').first().json.chatId,
  antwort: 'Den Auftrag konnte ich gerade nicht auswerten (das Sprachmodell hat nicht '
    + 'geantwortet). Bitte schick ihn noch einmal - Verwaltungsauftraege am Sender '
    + 'brauchen das Modell.',
  tastatur: null,
} }];

// Ergebnis des Werkzeugs direkt an den Chat geben (ohne Sprachmodell).
const j = $json || {};
const text = String(j.ergebnis || j.output || '').trim();
return [{ json: {
  chatId: j.chatId || $('Eingabe').first().json.chatId,
  antwort: text || 'Das habe ich nicht verstanden. Sag zum Beispiel: spiele Juliet von Modern Talking.',
  tastatur: null,
} }];

// Antwort fuer Telegram aufbereiten (HTML, keine Sternchen). Kommt entweder vom
// Agenten oder aus dem Ersatzweg.
let text = String($json.antwort || '').trim();
if (!text) text = 'Das habe ich nicht verstanden. Sag zum Beispiel: spiele Juliet von Modern Talking.';
text = text.replace(/\*\*/g, '').replace(/^#+\s*/gm, '').replace(/`/g, '');
return [{ json: { chatId: $json.chatId || $('Eingabe').first().json.chatId, antwort: text, tastatur: null } }];
